def T(k):
    return k * (k + 1) // 2

def f_prime(x, y):
    return T(x + y) + y

N = 0
limit = 100

for x in range(limit):
    for y in range(limit):
        if f_prime(x, y) % 2 != 0:
            N += 1

print(N)
